mapper.sql:
where a.deleted = 0

  and a.status = #{status}


  and a.type = #{type}


  and (
    lower(a.asset_no) like concat('%', lower(#{keyword}), '%')
    or lower(a.name) like concat('%', lower(#{keyword}), '%')
    or lower(a.location) like concat('%', lower(#{keyword}), '%')
    or lower(u.display_name) like concat('%', lower(#{keyword}), '%')
  )
